import sys
from collections import defaultdict, deque

def is_caterpillar(graph):
    def bfs(start):
        visited = set()
        queue = deque([start])
        path = []
        while queue:
            node = queue.popleft()
            if node in visited:
                continue
            visited.add(node)
            path.append(node)
            for neighbor in graph[node]:
                if neighbor not in visited:
                    queue.append(neighbor)
        return path, visited

    if not graph:
        return True

    start = next(iter(graph))
    path, visited = bfs(start)
    if len(visited) < len(graph):
        return False

    path_set = set(path)
    for node in path:
        for neighbor in graph[node]:
            if neighbor not in path_set:
                if len(graph[neighbor]) > 1:
                    return False
    return True

def min_operations_to_caterpillar(n, edges):
    graph = defaultdict(list)
    degree = [0] * (n + 1)

    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
        degree[u] += 1
        degree[v] += 1

    leaves = deque([i for i in range(1, n + 1) if degree[i] == 1])
    operations = 0

    while leaves:
        leaf = leaves.popleft()
        if degree[leaf] == 0:
            continue
        neighbor = graph[leaf][0]
        graph[neighbor].remove(leaf)
        degree[neighbor] -= 1
        degree[leaf] = 0
        if degree[neighbor] == 1:
            leaves.append(neighbor)
        operations += 1

    components = 0
    visited = set()

    def dfs(node):
        stack = [node]
        while stack:
            current = stack.pop()
            if current in visited:
                continue
            visited.add(current)
            for neighbor in graph[current]:
                if neighbor not in visited:
                    stack.append(neighbor)

    for i in range(1, n + 1):
        if degree[i] > 0 and i not in visited:
            dfs(i)
            components += 1

    return operations - (components - 1)

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    m = int(input[1])
    edges = [(int(input[2 + 2 * i]), int(input[3 + 2 * i])) for i in range(m)]
    print(min_operations_to_caterpillar(n, edges))

main()
